#include <bits/stdc++.h>
using namespace std;

static long ONES[17];
struct C {
    istream& in;
    ostream& out;
    string line;
    istringstream iss;
    bool eof;

    C(istream& input, ostream& output) : in(input), out(output), eof(false) {
        if (ONES[1] == 0) {
            ONES[1] = 1;
            for (int i = 2; i < 17; i++) {
                ONES[i] = 10 * ONES[i - 1] + 1;
            }
        }
        long x = nextLong();
        out << solve(x) << "\n";
    }

    long go(long x, int len) {
        x = abs(x);
        if (x % ONES[len] == 0) {
            return (x / ONES[len]) * len;
        }
        long low = x / ONES[len];
        long high = low + 1;

        long ret1 = low * len + go(x - low * ONES[len], len - 1);
        long ret2 = high * len + go(high * ONES[len] - x, len - 1);
        return min(ret1, ret2);
    }

    long solve(long x) {
        return go(x, 16);
    }

    long nextLong() {
        while (true) {
            if (!getline(in, line)) {
                eof = true;
                return 0;
            }
            iss.clear();
            iss.str(line);
            long val;
            if (iss >> val) {
                return val;
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    C c(cin, cout);
    return 0;
}

